examples.template:
MonarchSearchResults(
    groups: [
        MonarchSearchResultGroup(
            {{groups.0.label}},
            id: {{groups.0.id}},
            results: [
                MonarchSearchResult(
                    {{groups.0.items.0.title}},
                    id: {{groups.0.items.0.id}},
                    path: [{{groups.0.items.0.path.0}}, {{groups.0.items.0.path.1}}],
                    snippet: {{groups.0.items.0.snippet}},
                    meta: {{groups.0.items.0.meta}}
                ).metaAsBadge(),
                MonarchSearchResult(
                    {{groups.0.items.1.title}},
                    id: {{groups.0.items.1.id}},
                    path: [{{groups.0.items.1.path.0}}],
                    snippet: {{groups.0.items.1.snippet}}
                ),
            ],
            total: {{groups.0.total}},
            systemImage: "tray"
        ),
        MonarchSearchResultGroup(
            {{groups.1.label}},
            id: {{groups.1.id}},
            results: [
                MonarchSearchResult(
                    {{groups.1.items.0.title}},
                    id: {{groups.1.items.0.id}},
                    path: [{{groups.1.items.0.path.0}}],
                    meta: {{groups.1.items.0.meta}}
                ),
            ],
            systemImage: "calendar"
        ),
        MonarchSearchResultGroup(
            {{groups.2.label}},
            id: {{groups.2.id}},
            results: [
                MonarchSearchResult(
                    {{groups.2.items.0.title}},
                    id: {{groups.2.items.0.id}},
                    snippet: {{groups.2.items.0.snippet}}
                ),
            ],
            systemImage: "person.2"
        ),
    ],
    query: {{query}},
    onShowAll: { _ in },
    onSelect: { _, _ in }
)
.frame(height: 760)
